SELECT
    h.house_id,
    b.building_name,
    h.unit_no,
    h.house_number,
    h.area,
    CONCAT(ht.rooms, '室', ht.hall, '厅', ht.toilet, '卫') AS house_type_desc,
    h.orientation,
    r.name AS owner_name,
    r.phone AS owner_phone,
    h.status
FROM house h
LEFT JOIN building b ON h.building_id = b.building_id
LEFT JOIN house_type ht ON h.house_type_id = ht.house_type_id
LEFT JOIN house_resident_auth hra ON h.house_id = hra.house_id AND hra.is_main = 1 AND hra.audit_status = 2
LEFT JOIN resident r ON hra.resident_id = r.resident_id AND r.type = 1


        AND h.building_id = #{query.buildingId}


        AND h.unit_no = #{query.unitNo}


        AND h.status = #{query.status}


        AND h.area >= #{query.minArea}


        AND h.area <= #{query.maxArea}


        AND ht.rooms = #{query.rooms}


        AND ht.hall = #{query.hall}


        AND ht.toilet = #{query.toilet}


        AND h.orientation = #{query.orientation}


        AND r.name LIKE CONCAT('%', #{query.ownerName}, '%')


        AND (r.name LIKE CONCAT('%', #{query.keyword}, '%')
             OR r.phone LIKE CONCAT('%', #{query.keyword}, '%')
             OR h.house_number LIKE CONCAT('%', #{query.keyword}, '%'))


ORDER BY h.house_id ASC

SELECT house_id FROM house
WHERE building_id = #{buildingId}
AND unit_no = #{unitNo}
AND house_number = #{houseNumber}
